CREATE TABLE IF NOT EXISTS business_profiles (workspace_id text PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE, industry text NOT NULL DEFAULT 'general' CHECK(industry IN ('general','real_estate','medical','automotive','beauty','ecommerce')), currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','EUR','GBP','CAD','AUD')), auto_stage boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS conversations_tenant_id ON conversations(workspace_id,id);
CREATE TABLE IF NOT EXISTS brain_entries (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('product','service','faq','offer','competitor','playbook','voice')), title text NOT NULL, content text NOT NULL, price_minor bigint CHECK(price_minor>=0 AND price_minor<=100000000000), currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','EUR','GBP','CAD','AUD')), approved boolean NOT NULL DEFAULT false, expires_at bigint, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS brain_links (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, from_id text NOT NULL, to_id text NOT NULL, relation text NOT NULL CHECK(relation IN ('answers','supports','competes_with','bundles')), FOREIGN KEY(workspace_id,from_id) REFERENCES brain_entries(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,to_id) REFERENCES brain_entries(workspace_id,id) ON DELETE CASCADE, UNIQUE(workspace_id,from_id,to_id,relation), CHECK(from_id<>to_id));
CREATE TABLE IF NOT EXISTS deals (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, conversation_id text NOT NULL UNIQUE, stage text NOT NULL DEFAULT 'new' CHECK(stage IN ('new','qualified','proposed','negotiation','won','lost')), value_minor bigint CHECK(value_minor>=0 AND value_minor<=100000000000), currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','EUR','GBP','CAD','AUD')), expected_close date, product_id text, qualification jsonb NOT NULL DEFAULT '{"budgetMinor":null,"authority":"unknown","need":"","timelineDate":null}', campaign text NOT NULL DEFAULT '', source text NOT NULL, escalated boolean NOT NULL DEFAULT false, escalation_reason text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id) ON DELETE CASCADE, UNIQUE(workspace_id,id));
CREATE INDEX IF NOT EXISTS deals_pipeline ON deals(workspace_id,stage,currency,expected_close);
CREATE TABLE IF NOT EXISTS deal_events (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, deal_id text NOT NULL, actor_id text, kind text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,deal_id) REFERENCES deals(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS deal_outcomes (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, deal_id text NOT NULL UNIQUE, outcome text NOT NULL CHECK(outcome IN ('won','lost')), reason text NOT NULL, note text NOT NULL DEFAULT '', value_minor bigint, currency text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,deal_id) REFERENCES deals(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS revenue_events (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, deal_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('payment','refund')), amount_minor bigint NOT NULL CHECK(amount_minor>0 AND amount_minor<=100000000000), currency text NOT NULL, reference text NOT NULL, occurred_at bigint NOT NULL, client_key text NOT NULL, actor_id text NOT NULL, FOREIGN KEY(workspace_id,deal_id) REFERENCES deals(workspace_id,id) ON DELETE CASCADE, UNIQUE(workspace_id,client_key), UNIQUE(workspace_id,kind,reference));
CREATE TABLE IF NOT EXISTS deal_quotes (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, deal_id text NOT NULL, lines jsonb NOT NULL, total_minor bigint NOT NULL, valid_days integer NOT NULL DEFAULT 7 CHECK(valid_days BETWEEN 1 AND 30), currency text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','accepted','rejected')), expires_at bigint NOT NULL, client_key text NOT NULL, text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,deal_id) REFERENCES deals(workspace_id,id) ON DELETE CASCADE, UNIQUE(workspace_id,client_key));
CREATE TABLE IF NOT EXISTS appointments (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, deal_id text NOT NULL, title text NOT NULL, start_at bigint NOT NULL, end_at bigint NOT NULL, resource text NOT NULL DEFAULT 'Business', status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','cancelled')), client_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,deal_id) REFERENCES deals(workspace_id,id) ON DELETE CASCADE, UNIQUE(workspace_id,client_key));
CREATE INDEX IF NOT EXISTS appointments_resource ON appointments(workspace_id,resource,start_at,end_at);
CREATE TABLE IF NOT EXISTS sales_tasks (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, deal_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('follow_up','escalation')), due_at bigint NOT NULL, status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','ready','done','cancelled')), text text NOT NULL, reason text NOT NULL DEFAULT '', anchor_id text, client_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,deal_id) REFERENCES deals(workspace_id,id) ON DELETE CASCADE, UNIQUE(workspace_id,client_key));
CREATE TABLE IF NOT EXISTS reply_feedback (workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, message_id text NOT NULL REFERENCES messages(id) ON DELETE CASCADE, label text NOT NULL CHECK(label IN ('helpful','unhelpful')), actor_id text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,message_id));